<?php
namespace App\Http\Controllers\Api\Hr;
use App\Http\Controllers\Controller;use App\Models\Staff;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class HrIntegrationDeliveryController extends Controller{
 public function pending(Request$r):JsonResponse{$a=$this->actor($r);$d=$r->validate(['target_system'=>['required',Rule::in(['accounting','accounting_direct','payroll','procurement'])],'limit'=>['nullable','integer','min:1','max:500']]);$rows=DB::table('hr_accounting_outbox')->where('company_id',$a->company_id)->where('target_system',$d['target_system'])->whereIn('status',['pending','failed'])->where('available_at','<=',now())->select(['id','event_type','aggregate_type','aggregate_id','target_system','payload','payload_checksum','status','attempts','available_at','created_at'])->orderBy('available_at')->limit($d['limit']??100)->get();return response()->json(['status'=>'success','data'=>$rows]);}
 public function acknowledge(Request$r,string$id):JsonResponse{$d=$r->validate(['target_system'=>['required',Rule::in(['accounting','accounting_direct','payroll','procurement'])],'delivery_key'=>['required','string','max:200'],'payload_checksum'=>['required','string','size:64'],'outcome'=>['required',Rule::in(['accepted','rejected'])],'external_reference'=>['nullable','string','max:200'],'response_message'=>['nullable','string','max:4000'],'response_checksum'=>['nullable','string','size:64']]);return DB::transaction(function()use($r,$id,$d){$outbox=DB::table('hr_accounting_outbox')->where('id',$id)->lockForUpdate()->first();abort_unless($outbox,404);$this->company($r,$outbox->company_id);abort_unless($outbox->target_system===$d['target_system'],422,'Adapter target does not match the outbox contract.');abort_unless(hash_equals($outbox->payload_checksum,$d['payload_checksum']),409,'Payload checksum does not match the frozen outbox payload.');if($old=DB::table('hr_integration_deliveries')->where('delivery_key',$d['delivery_key'])->first()){abort_unless($old->outbox_id===$id&&$old->target_system===$d['target_system']&&$old->payload_checksum===$d['payload_checksum']&&$old->status===$d['outcome'],409,'Delivery key was reused with different evidence.');return response()->json(['status'=>'success','data'=>$old,'idempotent_replay'=>true]);}abort_if($outbox->status==='acknowledged',409,'Outbox event is already acknowledged.');$deliveryId=(string)Str::uuid();DB::table('hr_integration_deliveries')->insert(['id'=>$deliveryId,'outbox_id'=>$id,'target_system'=>$d['target_system'],'delivery_key'=>$d['delivery_key'],'payload_checksum'=>$d['payload_checksum'],'status'=>$d['outcome'],'external_reference'=>$d['external_reference']??null,'response_checksum'=>$d['response_checksum']??null,'response_message'=>$d['response_message']??null,'acknowledged_by'=>$r->user()->id,'acknowledged_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('hr_accounting_outbox')->where('id',$id)->update(['status'=>$d['outcome']==='accepted'?'acknowledged':'failed','attempts'=>DB::raw('attempts + 1'),'acknowledged_at'=>$d['outcome']==='accepted'?now():null,'external_reference'=>$d['external_reference']??null,'last_error'=>$d['outcome']==='rejected'?($d['response_message']??'Adapter rejected the delivery.'):null,'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_integration_deliveries')->find($deliveryId)],201);});}
 private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function company(Request$r,string$id):void{abort_unless($this->actor($r)->company_id===$id,403,'Integration event is outside your legal entity.');}
}
